169	     * Run the simulation from its current state for the given number of steps.
170	     * Stop before the given number of steps if it ceases to be viable.
171	     * @param numSteps The number of steps to run for.
172	     */
173	    public void simulate(int numSteps)
174	    {
175	        playingSimulation = true;
176	        remainingSteps = numSteps;
177	
178	        int completedSteps = 0;
179	        while(playingSimulation) {
180	            for(int currentStep = 0;
181	                    currentStep < numSteps && playingSimulation && currentState.isViable();
182	                    currentStep++) {
183	                simulateOneStep();
184	                completedSteps++;
185	//                delay(60);   // uncomment this to run more slowly
186	            }
187	            if(!currentState.isViable()) {
188	                updateBestSimulationResult(completedSteps);
189	                playingSimulation = false;
190	            }
191	        }
192	
193	        remainingSteps = Math.max(0, numSteps - completedSteps);
194	    }
